ALTER TABLE users ADD COLUMN username VARCHAR(80) NULL AFTER id;
CREATE UNIQUE INDEX users_username_unique ON users(username);
CREATE TABLE campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, summary TEXT, body MEDIUMTEXT NOT NULL, image_path VARCHAR(255), status VARCHAR(30) NOT NULL DEFAULT 'draft', starts_at DATETIME NULL, ends_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE media_assets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uploader_id BIGINT UNSIGNED NOT NULL, original_name VARCHAR(255) NOT NULL, file_path VARCHAR(255) NOT NULL UNIQUE, mime_type VARCHAR(100) NOT NULL, file_size BIGINT UNSIGNED NOT NULL, alt_text VARCHAR(255), category VARCHAR(80), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(uploader_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE pages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, slug VARCHAR(160) NOT NULL UNIQUE, body MEDIUMTEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'draft', seo_title VARCHAR(180), meta_description VARCHAR(255), updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE navigation_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, label VARCHAR(100) NOT NULL, url VARCHAR(255) NOT NULL, location VARCHAR(40) NOT NULL DEFAULT 'primary', parent_id BIGINT UNSIGNED NULL, position INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY(parent_id) REFERENCES navigation_items(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE homepage_sections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, section_key VARCHAR(80) NOT NULL UNIQUE, heading VARCHAR(180), description TEXT, position INT NOT NULL DEFAULT 0, record_limit INT NOT NULL DEFAULT 3, source_mode VARCHAR(20) NOT NULL DEFAULT 'latest', is_visible TINYINT(1) NOT NULL DEFAULT 1, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE content_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reporter_id BIGINT UNSIGNED NOT NULL, entity_type VARCHAR(50) NOT NULL, entity_id BIGINT UNSIGNED NOT NULL, reason VARCHAR(80) NOT NULL, details TEXT, status VARCHAR(30) NOT NULL DEFAULT 'open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(reporter_id) REFERENCES users(id), INDEX(status,created_at)) ENGINE=InnoDB;
CREATE TABLE moderation_actions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, moderator_id BIGINT UNSIGNED NOT NULL, report_id BIGINT UNSIGNED NULL, action VARCHAR(80) NOT NULL, notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(moderator_id) REFERENCES users(id), FOREIGN KEY(report_id) REFERENCES content_reports(id)) ENGINE=InnoDB;
